import { AreaSeriesChart } from "expo-charts";

const data = [
  { month: "Jan", desktop: 186, mobile: 80 },
  { month: "Feb", desktop: 305, mobile: 200 },
  { month: "Mar", desktop: 237, mobile: 120 },
];

const config = {
  desktop: { label: "Desktop" },
  mobile: { label: "Mobile", variant: "hatched" },
};

export function Visitors() {
  return (
    <AreaSeriesChart
      data={data}
      config={config}
      xKey="month"
      stacked
      curve="natural"
      fillVariant="gradient"
      backgroundVariant="dots"
      showLegend
    />
  );
}

import { BarSeriesChart } from "expo-charts";

<BarSeriesChart
  data={data}
  config={{ desktop: { label: "Desktop" }, mobile: { label: "Mobile", variant: "hatched" } }}
  xKey="month"
  radius={8}
  glow
  bufferLast
  showLabels
/>

import { PillBarChart } from "expo-charts";

const steps = [
  { label: "12", value: 2140 },
  { label: "13", value: 2960 },
  { label: "14", value: 2710, badge: "-8%" },
  { label: "15", value: 3240 },
  { label: "16", value: 3680 },
];

<PillBarChart
  data={steps}
  height={120}
  activeGradient={["#C3E550", "#4C9A3B"]}
  defaultIndex={4}
  dimAfter={4}
  activeDot
  onSelect={(i, d) => setShown(d)}
/>
